insert into metiers (slug, nom, description, ordre) values ($t$vente-commercial$t$, $t$Vente / Commercial$t$, $t$Gemini est recommandé pour la prospection et le suivi CRM connectés à Gmail ; ChatGPT en repli si CRM/messagerie Microsoft.$t$, 1);
insert into metiers (slug, nom, description, ordre) values ($t$btp-gestion-de-chantier$t$, $t$BTP / Gestion de chantier$t$, $t$Gemini est recommandé pour la planification et le suivi documentaire ; Claude en second choix pour l'analyse de risques sur de longs rapports.$t$, 2);
insert into metiers (slug, nom, description, ordre) values ($t$comptabilite$t$, $t$Comptabilité$t$, $t$Gemini est recommandé si les outils comptables sont déjà connectés à Sheets ; ChatGPT sinon.$t$, 3);
insert into metiers (slug, nom, description, ordre) values ($t$secretariat-administration$t$, $t$Secrétariat / Administration$t$, $t$Gemini est recommandé pour la gestion d'agenda/mail au quotidien ; c'est l'écart le plus faible des 12 métiers, les 3 IA restent utilisables.$t$, 4);
insert into metiers (slug, nom, description, ordre) values ($t$logistique-supply-chain$t$, $t$Logistique / Supply Chain$t$, $t$Gemini est recommandé pour le suivi fournisseurs et la prévision si les données sont dans Sheets ; un MCP Dynamics 365 est conseillé pour Claude/ChatGPT sinon.$t$, 5);
insert into metiers (slug, nom, description, ordre) values ($t$service-clientele$t$, $t$Service clientèle$t$, $t$Gemini est légèrement devant, mais c'est le métier où les 3 IA sont les plus proches ; le facteur décisif reste l'outil de ticketing utilisé.$t$, 6);
insert into metiers (slug, nom, description, ordre) values ($t$marketing$t$, $t$Marketing$t$, $t$Gemini est nettement devant grâce à la génération/édition d'image et de vidéo native ; Claude est à écarter pour ce métier, sauf pour la stratégie/rédaction pure.$t$, 7);
insert into metiers (slug, nom, description, ordre) values ($t$communication$t$, $t$Communication$t$, $t$La même logique que pour le Marketing s'applique, avec un écart encore plus marqué en faveur de Gemini.$t$, 8);
insert into metiers (slug, nom, description, ordre) values ($t$ressources-humaines$t$, $t$Ressources humaines$t$, $t$Gemini est recommandé pour la présélection de CV et le suivi de formation connectés ; Claude est une alternative solide pour l'analyse qualitative fine des candidatures.$t$, 9);
insert into metiers (slug, nom, description, ordre) values ($t$journalisme$t$, $t$Journalisme$t$, $t$Gemini est recommandé pour la recherche de plans vidéo et le montage ; ChatGPT est correct en repli pour la partie rédactionnelle pure.$t$, 10);
insert into metiers (slug, nom, description, ordre) values ($t$graphisme$t$, $t$Graphisme$t$, $t$Gemini est très largement devant grâce à l'édition d'image conversationnelle ; Claude est quasiment inutilisable seul sur ce métier.$t$, 11);
insert into metiers (slug, nom, description, ordre) values ($t$montage-video$t$, $t$Montage vidéo$t$, $t$Gemini est très largement devant grâce à Gemini Omni (montage conversationnel direct) ; Claude est quasiment inutilisable seul sur ce métier.$t$, 12);
